print("big sum:", r["groups"][0]["metrics"]["s"], "avg:", r["groups"][0]["metrics"]["a"])

try:
    s.aggregate({"records":[{"a":1}],"group_by":["/missing"],"metrics":[],"minimum_group_size":2})
except InvalidGroupBy: print("ok: group_by checked before metrics")

# average rounding correctness with huge total: (1e30+1)/3 -> 333333333333333333333333333333.666667
r = s.aggregate({"records":[{"v":10**30+1},{"v":0},{"v":0}],"group_by":[],"metrics":[{"name":"a","operation":"average","field":"/v"}],"minimum_group_size":2})
print("big avg:", r["groups"][0]["metrics"]["a"])
